UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Repari singur fisurile din perete</h2>\n    <p>Kit cu pastă și rolă pentru fisuri, găuri mici și pete. Fără trafalet, fără tavă, fără multe unelte.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/7c5fc6cd-a6c9-48af-9ca1-b9d89a5af3d6-1.webp\" alt=\"Kitul pentru reparat pereți: 2 role reparatoare, 2 tuburi cu pastă și accesorii\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Tot ce îți trebuie, într-un kit</h3>\n      <ul>\n        <li>2 role reparatoare și 2 tuburi cu pastă</li>\n        <li>Pentru fisuri, găuri mici și imperfecțiuni</li>\n        <li>Îți rămâne un set de rezervă</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/7c5fc6cd-a6c9-48af-9ca1-b9d89a5af3d6-2.webp\" alt=\"Bărbat care dă cu rola reparatoare pe perete\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Dai cu rola direct pe perete</h3>\n      <ul>\n        <li>Aplici direct, fără pregătiri complicate</li>\n        <li>Rola lasă un aspect uniform</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/7c5fc6cd-a6c9-48af-9ca1-b9d89a5af3d6-3.webp\" alt=\"Pașii de reparare: perete pătat, pastă pusă din tub și nivelare cu spatula\" width=\"480\" height=\"480\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Umpli gaura și nivelezi cu spatula</h3>\n      <ul>\n        <li>Pui pasta direct din tub</li>\n        <li>Întinzi și nivelezi cu spatula</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Cureți locul și umpli fisura cu pastă din tub.</li>\n      <li>Nivelezi cu spatula și lași să se usuce.</li>\n      <li>Treci cu rola peste loc, pentru un aspect uniform.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>4 produse în total (ofertă 2+2)</li>\n      <li>2 kituri cu rolă pentru repararea pereților</li>\n      <li>2 tuburi cu pastă reparatoare</li>\n      <li>Accesoriile de aplicare din poză</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Kit pentru repararea și retușarea pereților</td></tr>\n        <tr><th>Conținut</th><td>2 kituri cu rolă + 2 tuburi cu pastă reparatoare + accesorii de aplicare</td></tr>\n        <tr><th>Se folosește pentru</th><td>Fisuri, găuri mici și imperfecțiuni ale pereților</td></tr>\n        <tr><th>Aplicare</th><td>Pastă din tub nivelată cu spatula, apoi rolă</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Am nevoie de alte unelte?</h4>\n    <p>Nu ai nevoie de trafalet sau tavă. Pasta se pune din tub, iar produsul din kit se aplică direct cu rola lui.</p>\n    <h4>Rezultatul este la fel pe orice perete?</h4>\n    <p>Rezultatele pot varia în funcție de suprafață, de cum o pregătești și de cum aplici produsul.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = '7c5fc6cd-a6c9-48af-9ca1-b9d89a5af3d6';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Mașina de spălat stă pe loc, mai liniștită</h2>\n    <p>Picioarele antișoc se pun sub mașina de spălat. Absorb vibrațiile, reduc zgomotul și protejează podeaua. Primești 8 bucăți.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A001-1.webp\" alt=\"Picioare antișoc sub mașina de spălat, cu mopul care intră ușor dedesubt\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Faci curat ușor sub mașină</h3>\n      <ul>\n        <li>Înalță mașina de spălat de la podea</li>\n        <li>Mopul și aspiratorul intră lejer dedesubt</li>\n        <li>Absorb vibrațiile la stoarcere</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A001-2.webp\" alt=\"Picioare antiderapante sub mașina de spălat, frigider și masă\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Bune și la frigider sau masă</h3>\n      <ul>\n        <li>Mașina de spălat nu mai „merge” prin baie</li>\n        <li>Ajută la prevenirea zgârieturilor pe gresie și parchet</li>\n        <li>Al doilea set îl pui la frigider sau mobilă</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A001-3.webp\" alt=\"Picior antișoc gri, folosit la masă, aragaz, mașină de spălat și canapea\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Un picior, multe folosiri în casă</h3>\n      <ul>\n        <li>Merg la aragaz, uscător, mese, scaune, canapele</li>\n        <li>Rezistente, țin greutatea electrocasnicelor mari</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum le folosești</h3>\n    <ol>\n      <li>Ridici un colț al mașinii de spălat.</li>\n      <li>Pui piciorul antișoc sub piciorul mașinii.</li>\n      <li>Repeți la toate cele 4 colțuri. Nu ai nevoie de unelte.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>4 picioare antiderapante și antișoc</li>\n      <li>Încă 4 picioare gratis (oferta 4+4)</li>\n      <li>În total: 8 bucăți în colet</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Set</th><td>4 + 4 bucăți (8 în total)</td></tr>\n        <tr><th>Funcții</th><td>Antiderapant, antișoc, reducere zgomot și vibrații</td></tr>\n        <tr><th>Compatibilitate</th><td>Mașină de spălat, uscător, frigider, aragaz, mobilier</td></tr>\n        <tr><th>Protecție podea</th><td>Gresie, parchet, laminat</td></tr>\n        <tr><th>Montaj</th><td>Rapid, fără unelte</td></tr>\n        <tr><th>Culoare</th><td>Gri</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Câte bucăți primesc?</h4>\n    <p>Primești 8 picioare: un set de 4 pentru mașina de spălat și încă un set de 4 pentru frigider sau mobilă.</p>\n    <h4>Am nevoie de unelte la montaj?</h4>\n    <p>Nu. Ridici colțul, pui piciorul dedesubt și gata. Durează cam 2 minute.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A001';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Pantofii care te strâng devin mai comozi</h2>\n    <p>Șanurile reglabile lărgesc și alungesc încălțămintea în 24 de ore. Le pui seara în pantofi și rotești mânerele.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A002-1.webp\" alt=\"Șan reglabil într-un adidas, cu mâner pentru lărgit și mâner pentru alungit\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Lărgește și alungește pantoful</h3>\n      <ul>\n        <li>Un mâner pentru lărgit, unul pentru alungit</li>\n        <li>Accesorii mici pentru locul unde te strânge</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A002-2.webp\" alt=\"Șanuri unisex în pantof de damă și pantof bărbătesc, cu accesoriile incluse\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Pentru femei și pentru bărbați</h3>\n      <ul>\n        <li>Mărimi de la 30 la 47, în 4 variante</li>\n        <li>Se agață în dulap de mânerul în U</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A002-3.webp\" alt=\"Șan din ABS cu suprafață netedă, comparat cu șanuri din lemn care crapă și zgârie\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Din ABS, nu din lemn</h3>\n      <ul>\n        <li>Nu crapă, nu are așchii, nu zgârie</li>\n        <li>Suprafață netedă, nu deformează încălțămintea</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A002-4.webp\" alt=\"Șan universal, potrivit pentru adidași, sandale, pantofi eleganți, balerini și pantofi cu toc\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Merg la multe feluri de încălțăminte</h3>\n      <ul>\n        <li>Adidași, teniși, pantofi eleganți</li>\n        <li>Balerini, sandale, pantofi cu toc</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum le folosești</h3>\n    <ol>\n      <li>Introduci șanurile în pantofi.</li>\n      <li>Rotești mânerul rotund pentru alungit și mânerul în U pentru lărgit.</li>\n      <li>Aștepți 24 de ore și scoți șanurile.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 șanuri reglabile (1+1): unul pentru stângul, unul pentru dreptul</li>\n      <li>Accesorii pentru lărgit anumite zone</li>\n      <li>1 accesoriu pentru înălțat încălțămintea</li>\n      <li>1 geantă de depozitare și 1 încălțător</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Set</th><td>2 șanuri (stâng + drept)</td></tr>\n        <tr><th>Mărimi compatibile</th><td>4 variante: 30-36, 35-42, 38-44, 40-47</td></tr>\n        <tr><th>Funcții</th><td>Lărgire, alungire, înălțare, lărgire zone specifice</td></tr>\n        <tr><th>Material corp</th><td>ABS</td></tr>\n        <tr><th>Mâner</th><td>Metalic inoxidabil, în formă de U (pentru agățare)</td></tr>\n        <tr><th>Tip</th><td>Unisex – damă și bărbați</td></tr>\n        <tr><th>Compatibilitate</th><td>Adidași, pantofi, teniși, balerini, sandale, pantofi cu toc</td></tr>\n        <tr><th>Timp de acțiune</th><td>24 de ore</td></tr>\n        <tr><th>Culoare</th><td>Galben / Negru</td></tr>\n        <tr><th>Curățare</th><td>Ștergere sau spălare cu apă – rezistă la apă</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Câte șanuri primesc?</h4>\n    <p>Primești 2 șanuri, adică o pereche: unul pentru pantoful stâng și unul pentru cel drept.</p>\n    <h4>Ce mărime aleg?</h4>\n    <p>Alegi varianta în care intră mărimea ta: 30-36, 35-42, 38-44 sau 40-47.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A002';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Repari fisurile din perete singur, în câteva minute</h2>\n    <p>Crema albă se aplică direct din tub și se netezește cu racleta. Nu ai nevoie de zugrav și nici de experiență.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A003-1.webp\" alt=\"Tub de cremă reparatoare și un perete din sufragerie, înainte cu fisuri și după reparație\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Pereți curați, fără șantier în casă</h3>\n      <ul>\n        <li>Acoperă fisuri, găuri de cuie și dibluri</li>\n        <li>Bună și pentru var căzut sau crăpat</li>\n        <li>Cremă albă, se aplică direct din tub</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A003-2.webp\" alt=\"Fisură adâncă în perete, înainte și după aplicarea cremei reparatoare\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Reparația aproape că nu se vede</h3>\n      <ul>\n        <li>Aplicată corect, crema se contopește cu peretele</li>\n        <li>Se usucă rapid</li>\n        <li>După uscare poți bate un cui în ea</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A003-3.webp\" alt=\"Cei 4 pași de aplicare: găsești zona, aplici crema, o întinzi și netezești cu racleta\" width=\"480\" height=\"480\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Ușor de folosit de oricine</h3>\n      <ul>\n        <li>Apeși tubul și crema umple fisura</li>\n        <li>Netezești cu racleta din colet</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Apeși tubul și pui crema direct pe fisură sau gaură.</li>\n      <li>Întinzi crema uniform peste zonă.</li>\n      <li>Netezești cu racleta și lași să se usuce.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 kituri de reparat pereții (1+1), a câte 200 g fiecare</li>\n      <li>Aplicator cu vârf de precizie</li>\n      <li>Racletă pentru nivelare</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Gramaj</th><td>200 g / set (2 seturi în oferta 1+1)</td></tr>\n        <tr><th>Culoare</th><td>Alb</td></tr>\n        <tr><th>Uscare</th><td>Rapidă</td></tr>\n        <tr><th>Rezistență</th><td>Susține cui sau șurub după uscare</td></tr>\n        <tr><th>Acoperă</th><td>Fisuri, urme de cuie, pete, var căzut sau crăpat, urme de mobilier</td></tr>\n        <tr><th>Aplicare</th><td>Direct din tub + racletă de nivelare</td></tr>\n        <tr><th>Utilizare</th><td>Proiecte casnice și reparații mici, fără ajutor profesional</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Câte tuburi primesc?</h4>\n    <p>Primești 2 kituri, fiecare cu 200 g de cremă albă.</p>\n    <h4>Pot bate un cui în zona reparată?</h4>\n    <p>Da. După ce crema s-a uscat, zona reparată ține un cui sau un șurub.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A003';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Toci legumele cu o singură apăsare</h2>\n    <p>Pui leguma pe lamă și cobori capacul. Cubulețele cad direct în recipient. Primești 2 seturi complete.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A004-1.webp\" alt=\"Oferta 1+1: două seturi complete de feliator de legume\" width=\"720\" height=\"460\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Două seturi complete în colet</h3>\n      <ul>\n        <li>Primești 2 seturi, nu unul</li>\n        <li>Fiecare set are toate lamele și accesoriile</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A004-2.webp\" alt=\"Feliator cu recipient colector, lame interschimbabile, separator de ou, curățător și coș de scurgere\" width=\"600\" height=\"600\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>14 feluri de tăiere</h3>\n      <ul>\n        <li>Cubulețe, felii, julienne și răzuire</li>\n        <li>Legumele cad în recipient, blatul rămâne curat</li>\n        <li>Protecția de mână ține degetele departe de lame</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A004-3.webp\" alt=\"Legume și fructe care se pot tăia: ceapă, castraveți, morcovi, cartofi, roșii, varză, mere\" width=\"575\" height=\"560\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Taie aproape orice legumă</h3>\n      <ul>\n        <li>Ceapă, morcovi, cartofi, dovlecei, castraveți</li>\n        <li>Roșii, varză, ardei, mere, căpșuni</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A004-4.webp\" alt=\"Mod de folosire în 4 pași: tai leguma, pui lama, apeși capacul, cureți lama\" width=\"571\" height=\"564\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Simplu de folosit și de curățat</h3>\n      <ul>\n        <li>Bucățile ies uniforme și se gătesc la fel</li>\n        <li>Toate lamele se strâng înăuntru, în dulap</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Tai leguma în bucăți potrivite și alegi lama dorită.</li>\n      <li>Pui leguma pe lamă și apeși capacul.</li>\n      <li>După folosire, cureți lama cu curățătorul din set.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 seturi complete (1+1), fiecare cu:</li>\n      <li>Feliator cu recipient colector și lame inox interschimbabile</li>\n      <li>Protecție pentru mână și presă de cartofi</li>\n      <li>Separator de ou, curățător și coș de scurgere</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Feliator / răzătoare / tocător de fructe și legume, 14 în 1</td></tr>\n        <tr><th>Tipuri de tăiere</th><td>14 – cubulețe, felii, julienne, răzuire</td></tr>\n        <tr><th>Lame</th><td>Inox, interschimbabile</td></tr>\n        <tr><th>Accesorii</th><td>Recipient colector, protecție pentru mână, presă cartofi, separator de ou, curățător, coș de scurgere</td></tr>\n        <tr><th>Cantitate</th><td>2 seturi complete (oferta 1+1)</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Câte seturi primesc?</h4>\n    <p>Primești 2 seturi complete în același colet.</p>\n    <h4>Este sigur pentru degete?</h4>\n    <p>Setul are o protecție pentru mână, care ține degetele departe de lame.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A004';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Karaoke acasă, cu boxă și 2 microfoane</h2>\n    <p>Pornești boxa, conectezi telefonul prin Bluetooth și cânți cu familia. Microfoanele sunt fără fir, iar boxa are lumini colorate.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A005-1.webp\" alt=\"Set karaoke cu boxă portabilă cu mâner și 2 microfoane fără fir\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Cântați în doi, fără fire</h3>\n      <ul>\n        <li>2 microfoane fără fir, pentru duete în familie</li>\n        <li>Sunet puternic și clar, cu bas</li>\n        <li>Mică și ușoară, o iei oriunde</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A005-2.webp\" alt=\"Boxa karaoke conectată prin Bluetooth la un telefon\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Se leagă ușor la telefon</h3>\n      <ul>\n        <li>Bluetooth: telefon, tabletă sau laptop</li>\n        <li>Are și mufă AUX, pentru cablu</li>\n        <li>Fără instalări, merge în câteva secunde</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A005-3.webp\" alt=\"Boxa karaoke cu lumini RGB în mai multe culori și 2 microfoane\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Lumini colorate care dau atmosferă</h3>\n      <ul>\n        <li>Lumini RGB care își schimbă culorile</li>\n        <li>Bună la zile de naștere și seri în familie</li>\n        <li>Un cadou frumos pentru copii și nepoți</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum o folosești</h3>\n    <ol>\n      <li>Pornești boxa.</li>\n      <li>Activezi Bluetooth pe telefon și alegi boxa.</li>\n      <li>Pui muzica preferată și cânți la microfon.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 boxă portabilă cu lumini RGB</li>\n      <li>2 microfoane fără fir</li>\n      <li>1 cablu de încărcare</li>\n      <li>1 manual de utilizare</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Set karaoke: boxă portabilă cu 2 microfoane fără fir</td></tr>\n        <tr><th>Conectare</th><td>Bluetooth și Aux-In</td></tr>\n        <tr><th>Compatibilitate</th><td>Telefon, tabletă, laptop</td></tr>\n        <tr><th>Lumini</th><td>RGB, în mai multe culori</td></tr>\n        <tr><th>Alimentare</th><td>Acumulator, cu cablu de încărcare inclus</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Merge cu telefonul meu?</h4>\n    <p>Da, dacă telefonul are Bluetooth. Se poate lega și cu cablu, prin mufa AUX.</p>\n    <h4>Trebuie să stea în priză?</h4>\n    <p>Nu. Boxa se încarcă cu cablul din colet și apoi merge fără priză.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A005';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Cartofi tăiați egal, dintr-o singură apăsare</h2>\n    <p>Pui cartoful, apeși mânerul și ies batoane egale, gata de prăjit. Aparatul este din inox, inclusiv lama.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A006-1.webp\" alt=\"Aparat din inox care taie un cartof în batoane egale la apăsarea mânerului\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Un cartof întreg, o apăsare</h3>\n      <ul>\n        <li>Batoane egale, care se prăjesc uniform</li>\n        <li>Cartofi pentru toată familia în câteva minute</li>\n        <li>Degetele stau departe de lamă</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A006-2.webp\" alt=\"Aparat de tăiat cartofi din inox, cu lamă detașabilă și mâner lung\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Din inox, cu lamă detașabilă</h3>\n      <ul>\n        <li>Construcție solidă din inox, nu din plastic</li>\n        <li>Lama se spală la mașina de spălat vase</li>\n        <li>Taie și morcovi, dovlecei, castraveți</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Pui cartoful în aparat.</li>\n      <li>Apeși mânerul până la capăt.</li>\n      <li>Scoți batoanele și speli lama.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 aparat de tăiat cartofi din inox</li>\n      <li>Lamă de tăiere din oțel inoxidabil</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Mașină de feliat cartofi și legume</td></tr>\n        <tr><th>Material</th><td>Inox (inclusiv lama de tăiere)</td></tr>\n        <tr><th>Tip alimente</th><td>Cartofi, morcovi, dovlecei și alte legume</td></tr>\n        <tr><th>Curățare</th><td>Lama se poate spăla la mașina de spălat vase</td></tr>\n        <tr><th>Culoare</th><td>Gri / Inox</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Taie doar cartofi?</h4>\n    <p>Nu. Taie și morcovi, dovlecei, castraveți și alte legume, în bucăți egale.</p>\n    <h4>Cum se curăță?</h4>\n    <p>Lama se scoate și se poate spăla la mașina de spălat vase.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A006';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Razi legumele repede, fără să-ți julești degetele</h2>\n    <p>Pui leguma în coș și învârți manivela. Legumele rase cad direct în bol, iar mâinile nu ating lamele.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A007-1.webp\" alt=\"Răzătoare cu manivelă care rade un morcov direct în bol\" width=\"640\" height=\"640\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Învârți manivela și e gata</h3>\n      <ul>\n        <li>Un bol de morcovi rași în scurt timp</li>\n        <li>Degetele stau departe de lame</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A007-2.webp\" alt=\"Cele 3 site: răzuire mică, răzuire mare și feliere, plus coșul de alimentare și butonul de fixare\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Trei lame din oțel inoxidabil</h3>\n      <ul>\n        <li>Răzuire fină, răzuire mare și feliere</li>\n        <li>Baza cu ventuză nu alunecă pe blat</li>\n        <li>Bună pentru legume, fructe, nuci, brânză</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A007-3.webp\" alt=\"Dimensiunile răzătoarei: 23 cm înălțime, 11,5 cm talpa, 8 cm mânerul\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Mică, încape ușor în dulap</h3>\n      <ul>\n        <li>Are doar 23 cm înălțime</li>\n        <li>Se demontează în câteva secunde</li>\n        <li>Se poate spăla la mașina de spălat vase</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum o folosești</h3>\n    <ol>\n      <li>Fixezi răzătoarea pe blat, cu ventuza și butonul de fixare.</li>\n      <li>Alegi lama și pui leguma în coșul de alimentare.</li>\n      <li>Învârți manivela, cu un bol așezat în față.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 răzătoare cu bază cu ventuză (oferta 1+1 = 2 bucăți)</li>\n      <li>Fiecare cu 3 lame din oțel inoxidabil: fină, mare, feliere</li>\n      <li>Fiecare cu mâner cu manivelă</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Lame incluse</th><td>3 (răzuire fină, răzuire grosieră, feliere)</td></tr>\n        <tr><th>Material lame</th><td>Oțel inoxidabil</td></tr>\n        <tr><th>Material corp</th><td>Plastic ABS rezistent</td></tr>\n        <tr><th>Fixare</th><td>Bază cu ventuză + buton de fixare</td></tr>\n        <tr><th>Înălțime</th><td>23 cm</td></tr>\n        <tr><th>Lățime talpă</th><td>11,5 cm</td></tr>\n        <tr><th>Mâner</th><td>8 cm</td></tr>\n        <tr><th>Funcționare</th><td>Manuală, fără curent electric</td></tr>\n        <tr><th>Curățare</th><td>Compatibilă cu mașina de spălat vase</td></tr>\n        <tr><th>Ideală pentru</th><td>Legume, fructe, nuci, migdale, brânză</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Alunecă pe blat când rad?</h4>\n    <p>Nu. Baza are ventuză și un buton de fixare, care o țin pe loc pe blat.</p>\n    <h4>Pot rade și altceva în afară de legume?</h4>\n    <p>Da. Merge și la fructe, nuci, migdale și brânză.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A007';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Repari petele de pe perete cu o rolă</h2>\n    <p>Vopseaua vine în tub, cu rola prinsă direct pe el. Apeși și dai pe perete, fără tăviță și fără pensule.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A008-1.webp\" alt=\"Oferta 1+1: două seturi complete cu tub de vopsea, rolă, șmirghel și mănuși\" width=\"720\" height=\"450\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Două seturi complete în colet</h3>\n      <ul>\n        <li>2 tuburi de vopsea a câte 500 ml</li>\n        <li>Fiecare set are rolă, șmirghel și mănuși</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A008-2.webp\" alt=\"Perete cu var cojit, crăpătură, mâzgălituri de carioca și pete, plus setul de reparat\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Acoperă multe feluri de urme</h3>\n      <ul>\n        <li>Crăpături, fisuri și var cojit</li>\n        <li>Pete de mucegai, umezeală sau grăsime</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A008-3.webp\" alt=\"Conținutul unui set: tub de vopsea 500 ml, rolă de aplicare, șmirghel și mănuși\" width=\"720\" height=\"608\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Ai tot ce îți trebuie în set</h3>\n      <ul>\n        <li>Șmirghel pentru pregătirea peretelui</li>\n        <li>Mănuși de protecție pentru mâini</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A008-4.webp\" alt=\"Bărbat care aplică vopseaua pe perete cu rola prinsă pe tub\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Dai cu rola direct pe perete</h3>\n      <ul>\n        <li>Vopseaua curge uniform prin rolă</li>\n        <li>Se usucă în 3–4 ore</li>\n        <li>Fără mirosuri iritante</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum o folosești</h3>\n    <ol>\n      <li>Șlefuiești zona cu șmirghelul din set.</li>\n      <li>Apeși tubul și treci cu rola peste pată sau crăpătură.</li>\n      <li>Lași să se usuce 3–4 ore.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 seturi complete (1+1), adică:</li>\n      <li>2 tuburi de vopsea de 500 ml, cu rolă</li>\n      <li>2 role pentru aplicare uniformă</li>\n      <li>2 perechi de mănuși și 2 bucăți de șmirghel</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Conținut net</th><td>500 ml / tub (2 tuburi în oferta 1+1)</td></tr>\n        <tr><th>Dimensiuni produs</th><td>Aprox. 21 × 11,5 × 7 cm</td></tr>\n        <tr><th>Timp de uscare</th><td>3–4 ore</td></tr>\n        <tr><th>Aplicare</th><td>Rolă integrată, fără unelte suplimentare</td></tr>\n        <tr><th>Formulă</th><td>Ecologică, fără mirosuri iritante</td></tr>\n        <tr><th>Acoperă</th><td>Crăpături, fisuri, pete, mâzgălituri, var cojit</td></tr>\n        <tr><th>Accesorii incluse</th><td>Rolă, mănuși, șmirghel</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Câte seturi primesc?</h4>\n    <p>Primești 2 seturi complete. Fiecare are un tub de 500 ml, rolă, mănuși și șmirghel.</p>\n    <h4>Am nevoie de pensule sau tăviță?</h4>\n    <p>Nu. Rola se prinde direct pe tub. Apeși tubul și vopseaua iese prin rolă.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A008';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Usuci și aranjezi părul cu un singur aparat</h2>\n    <p>Peria cu aer cald usucă părul și îi dă formă în același timp. Schimbi capătul și faci bucle, volum sau păr drept.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A009-1.webp\" alt=\"Perie electrică 5 în 1 cu aer cald și cele 5 accesorii de coafat\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>5 accesorii pe același mâner</h3>\n      <ul>\n        <li>Duză de uscare și perie de netezire</li>\n        <li>Perie rotundă pentru volum</li>\n        <li>2 capete de ondulare, pentru bucle</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A009-2.webp\" alt=\"Peria cu capăt de ondulare, cu perie rotundă și cu perie de netezire\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Coafare rapidă și ușoară</h3>\n      <ul>\n        <li>Usucă și coafează în același timp</li>\n        <li>Schimbi accesoriul cu un singur click</li>\n        <li>Un aparat și o priză, în loc de trei</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A009-3.webp\" alt=\"Detalii: buton de deblocare a periei, comutator de temperatură și filtru de aerisire\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Alegi căldura potrivită părului tău</h3>\n      <ul>\n        <li>3 trepte: aproximativ 63°C, 96°C și 136°C</li>\n        <li>Buton de deblocare pentru schimbarea periei</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum o folosești</h3>\n    <ol>\n      <li>Prinzi pe mâner accesoriul dorit.</li>\n      <li>Alegi treapta de temperatură din comutator.</li>\n      <li>Treci peria prin păr, șuviță cu șuviță.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 perie electrică cu aer cald, 1000W (corpul principal)</li>\n      <li>1 duză de uscare</li>\n      <li>1 perie de netezire / pieptănare</li>\n      <li>1 perie rotundă pentru volum</li>\n      <li>2 capete de ondulare</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Perie electrică multifuncțională 5 în 1, cu aer cald</td></tr>\n        <tr><th>Putere</th><td>1000W</td></tr>\n        <tr><th>Trepte de temperatură</th><td>3 trepte: aprox. 63°C, 96°C și 136°C</td></tr>\n        <tr><th>Funcții</th><td>Uscare, pieptănare, netezire, ondulare, volum</td></tr>\n        <tr><th>Accesorii</th><td>5 capete de stilizare interschimbabile</td></tr>\n        <tr><th>Lungime cablu</th><td>2,5 m</td></tr>\n        <tr><th>Culoare</th><td>Gri / Roz</td></tr>\n        <tr><th>Utilizare</th><td>Acasă, la salon sau în călătorii</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Merge și la păr lung și des?</h4>\n    <p>Da. Motorul de 1000W dă un flux de aer puternic, bun și pentru păr lung și des.</p>\n    <h4>Cum schimb accesoriul?</h4>\n    <p>Apeși butonul de deblocare, scoți capătul și îl prinzi pe celălalt.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A009';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Cântarul care îți arată mai mult decât kilogramele</h2>\n    <p>Te urci pe el și vezi greutatea pe ecran. Pe telefon apar și estimări pentru grăsime, mușchi și apă.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A010-1.webp\" alt=\"Persoană care se urcă pe cântarul inteligent, cu telefonul alături\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Te urci și pornește singur</h3>\n      <ul>\n        <li>Fără butoane de apăsat</li>\n        <li>Cântărirea ajunge pe telefon prin Bluetooth</li>\n        <li>Nu mai notezi nimic pe hârtie</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A010-2.webp\" alt=\"Conectarea cântarului cu telefonul prin aplicația OKOK International\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Se leagă ușor de telefon</h3>\n      <ul>\n        <li>Merge cu telefoane Android și iPhone</li>\n        <li>Aplicația OKOK International, fără abonament</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A010-3.webp\" alt=\"Cântar din sticlă neagră cu ecran LCD luminos, pe podea\" width=\"400\" height=\"400\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Ecran mare, ușor de citit</h3>\n      <ul>\n        <li>Ecran LCD luminos</li>\n        <li>Arată și temperatura din cameră</li>\n        <li>Sticlă securizată, cântărește până la 180 kg</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A010-4.webp\" alt=\"Cântarul și telefonul pe care se vede evoluția greutății\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Îți vezi evoluția în timp</h3>\n      <ul>\n        <li>Grafice cu greutatea pe termen lung</li>\n        <li>Până la 8 persoane, fiecare cu profilul său</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Scanezi codul QR de pe cutie și instalezi aplicația.</li>\n      <li>Pornești Bluetooth-ul pe telefon.</li>\n      <li>Te urci pe cântar și datele apar în aplicație.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 cântar inteligent, 26 × 26 cm</li>\n      <li>Baterii incluse</li>\n      <li>Manual de utilizare și cod QR pentru aplicație</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Cântar corporal digital cu Bluetooth și aplicație</td></tr>\n        <tr><th>Măsurători</th><td>19 indicatori estimați: greutate, grăsime corporală, masă musculară, apă, masă osoasă, IMC, BMR și alții</td></tr>\n        <tr><th>Tehnologie</th><td>Analiză bioelectrică (BIA)</td></tr>\n        <tr><th>Interval de cântărire</th><td>0,2 kg – 180 kg</td></tr>\n        <tr><th>Precizie</th><td>50 g</td></tr>\n        <tr><th>Ecran</th><td>LCD, afișează greutatea și temperatura camerei</td></tr>\n        <tr><th>Aplicație</th><td>OKOK International, pentru iOS și Android</td></tr>\n        <tr><th>Utilizatori</th><td>Până la 8 profiluri</td></tr>\n        <tr><th>Dimensiuni</th><td>26 × 26 cm</td></tr>\n        <tr><th>Material</th><td>Sticlă securizată</td></tr>\n        <tr><th>Alimentare</th><td>Baterii (incluse)</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Îl pot folosi fără telefon?</h4>\n    <p>Da. Greutatea și temperatura apar pe ecranul cântarului. Celelalte valori se văd doar în aplicație.</p>\n    <h4>Cât de exacte sunt valorile pentru grăsime și mușchi?</h4>\n    <p>Sunt estimări, bune pentru a-ți urmări evoluția în timp. Cântarul nu pune diagnostice și nu înlocuiește sfatul medicului.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A010';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Muți benzina sau apa fără să verși</h2>\n    <p>Strângi para de cauciuc de câteva ori și lichidul curge singur prin furtun. Nu mai tragi cu gura din furtun.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A011-1.webp\" alt=\"Pompă manuală cu pară de cauciuc, furtun transparent și două coliere\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Pompezi cu mâna, fără curent</h3>\n      <ul>\n        <li>Furtun transparent: vezi când curge lichidul</li>\n        <li>Colierele din oțel inoxidabil țin furtunul strâns</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A011-2.webp\" alt=\"Pompa folosită la rezervorul mașinii, la acvariu și la bidoane\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Bună la mașină, în casă, în grădină</h3>\n      <ul>\n        <li>Pentru benzină, motorină și apă</li>\n        <li>Schimbi ușor apa din acvariu</li>\n        <li>Golești bidoane și butoaie fără să le răstorni</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A011-3.webp\" alt=\"Pașii de folosire: furtunul în rezervor, celălalt capăt în canistră, strângi para\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Câteva strângeri și curge singur</h3>\n      <ul>\n        <li>Lichidul curge mai departe prin sifonare</li>\n        <li>Tu doar aștepți să se umple</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A011-4.webp\" alt=\"Conținutul setului: pară de cauciuc, furtun PVC și două coliere\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Mică, încape ușor în portbagaj</h3>\n      <ul>\n        <li>Para are 23,5 cm lungime</li>\n        <li>Compactă și ușoară, o ai mereu la îndemână</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum o folosești</h3>\n    <ol>\n      <li>Pui capătul de aspirare în recipientul plin.</li>\n      <li>Pui celălalt capăt în recipientul gol.</li>\n      <li>Strângi para de câteva ori, până pornește lichidul.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 pompe manuale cu pară de cauciuc (oferta 1+1 = 2 bucăți)</li>\n      <li>Furtun PVC transparent</li>\n      <li>Coliere de fixare din oțel inoxidabil</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Set</th><td>2 bucăți</td></tr>\n        <tr><th>Lungime furtun</th><td>2 m</td></tr>\n        <tr><th>Dimensiune pară</th><td>23,5 × 5,3 cm</td></tr>\n        <tr><th>Material pompă</th><td>Cauciuc durabil</td></tr>\n        <tr><th>Material furtun</th><td>PVC transparent, rezistent la ulei și temperaturi ridicate</td></tr>\n        <tr><th>Accesorii</th><td>Coliere de fixare din oțel inoxidabil</td></tr>\n        <tr><th>Lichide compatibile</th><td>Benzină, motorină, apă și alte lichide comune</td></tr>\n        <tr><th>Atenție</th><td>Nu este potrivită pentru lichide corozive</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Ce lichide pot transfera?</h4>\n    <p>Benzină, motorină, apă și alte lichide comune. Nu o folosi pentru lichide corozive.</p>\n    <h4>Are nevoie de curent sau baterii?</h4>\n    <p>Nu. Este manuală. Strângi para cu mâna și lichidul pornește.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A011';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Usuci și aranjezi părul cu o singură perie</h2>\n    <p>Peria suflă aer cald în timp ce te piepteni. Nu mai ții uscătorul într-o mână și peria în cealaltă.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A012-1.webp\" alt=\"Femeie care își usucă și își piaptănă părul cu peria cu aer cald\" width=\"571\" height=\"568\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Usucă și coafează în același timp</h3>\n      <ul>\n        <li>Usucă, îndreaptă, ondulează și dă volum</li>\n        <li>Putere de 1000 W, pentru uscare rapidă</li>\n        <li>Mâner care nu alunecă din mână</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A012-2.webp\" alt=\"Comparație: păr uscat cu o perie obișnuită și păr neted cu peria cu aer cald\" width=\"568\" height=\"581\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Păr mai neted și mai lucios</h3>\n      <ul>\n        <li>Ionii negativi ajută la reducerea electrizării</li>\n        <li>Părul se încrețește mai puțin</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A012-3.webp\" alt=\"Detalii ale periei: orificii de aer, vârf rece, mâner ergonomic și cablu rotativ\" width=\"552\" height=\"581\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Gândită să fie comodă</h3>\n      <ul>\n        <li>3 trepte: cald, mediu și rece</li>\n        <li>Peri din nailon, cu efect de masaj</li>\n        <li>Cablu de 2 metri, care se rotește 360°</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum o folosești</h3>\n    <ol>\n      <li>Bagi peria în priză și alegi treapta de căldură.</li>\n      <li>Treci peria prin păr, șuviță cu șuviță.</li>\n      <li>La final, treapta rece ajută la fixarea coafurii.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 perie cu aer cald, 1000 W</li>\n      <li>Cablu de alimentare rotativ, de 2 metri</li>\n      <li>Instrucțiuni de utilizare</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Putere</th><td>1000 W</td></tr>\n        <tr><th>Trepte de temperatură</th><td>3 (cald / mediu / rece)</td></tr>\n        <tr><th>Trepte de viteză</th><td>3</td></tr>\n        <tr><th>Tehnologie</th><td>Ioni negativi</td></tr>\n        <tr><th>Peri</th><td>Nailon, cu efect de masaj al scalpului</td></tr>\n        <tr><th>Cablu</th><td>2 m, rotativ 360°</td></tr>\n        <tr><th>Culoare</th><td>Negru / Roz</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Pot renunța la uscătorul de păr?</h4>\n    <p>Peria usucă și coafează în același timp, așa că o poți folosi în locul uscătorului și al periei obișnuite.</p>\n    <h4>La ce folosește treapta rece?</h4>\n    <p>Aerul rece ajută la fixarea coafurii după ce ai terminat de aranjat părul.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A012';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Îndrepți apa exact unde ai nevoie</h2>\n    <p>Extensia se prinde pe robinet și se rotește în orice direcție. Speli ușor vasele mari și colțurile chiuvetei.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A013-1.webp\" alt=\"Extensie rotativă montată pe robinet, arătată în mai multe poziții\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Se rotește 360° în trei puncte</h3>\n      <ul>\n        <li>3 articulații care se mișcă separat</li>\n        <li>Ajungi în fiecare colț al chiuvetei</li>\n        <li>Bună la bucătărie și la baie</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A013-2.webp\" alt=\"Jet de apă cu aerare îndreptat în sus din extensia de robinet\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Jet plin, cu mai puțină apă</h3>\n      <ul>\n        <li>Amestecă apa cu aer</li>\n        <li>Poate reduce consumul de apă cu până la 50%</li>\n        <li>Mai puțini stropi pe blat</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A013-3.webp\" alt=\"Extensia de robinet, cheia de montare și trei garnituri\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>O montezi singur, fără instalator</h3>\n      <ul>\n        <li>Cheie și garnituri incluse în pachet</li>\n        <li>Se potrivește pe majoritatea robinetelor standard</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum o folosești</h3>\n    <ol>\n      <li>Alegi garnitura potrivită pentru robinetul tău.</li>\n      <li>Înșurubezi extensia pe robinet și o strângi cu cheia.</li>\n      <li>Rotești brațul spre locul unde vrei să curgă apa.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 extensii rotative pentru robinet (oferta 1+1 = 2 bucăți)</li>\n      <li>Cheie de montare</li>\n      <li>Garnituri de etanșare</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Material</th><td>ABS</td></tr>\n        <tr><th>Rotație</th><td>360° pe 3 articulații independente</td></tr>\n        <tr><th>Moduri jet</th><td>1 (normal)</td></tr>\n        <tr><th>Compatibilitate</th><td>Robinete standard cu filet intern sau extern</td></tr>\n        <tr><th>Economie de apă</th><td>Până la 50%, prin aerare</td></tr>\n        <tr><th>Accesorii</th><td>Cheie de montare și garnituri de etanșare</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Se potrivește pe robinetul meu?</h4>\n    <p>Se potrivește pe majoritatea robinetelor standard, cu filet intern sau extern. În pachet găsești garnituri.</p>\n    <h4>Am nevoie de instalator?</h4>\n    <p>Nu. Se înșurubează pe robinet, iar cheia de montare este inclusă.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A013';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Suc proaspăt de fructe, la o apăsare de buton</h2>\n    <p>Tai fructul, îl pui pe con și apeși butonul. Motorul stoarce în locul tău, fără efort în mână.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A014-1.webp\" alt=\"Portocală tăiată, pusă pe conul storcătorului, și pahare cu suc proaspăt\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Stoarce singur, tu doar apeși</h3>\n      <ul>\n        <li>Motor de 45 W, sucul e gata repede</li>\n        <li>Conul ține fructul pe loc</li>\n        <li>Blatul rămâne curat</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A014-2.webp\" alt=\"Struguri și pepene puși în storcător și pahare cu suc\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Nu doar pentru portocale</h3>\n      <ul>\n        <li>Lămâi, grepfrut, rodie, struguri, pepene</li>\n        <li>Vas de 500 ml, suc pentru două persoane</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A014-3.webp\" alt=\"Piesele storcătorului clătite sub jet de apă, la chiuvetă\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Se spală repede, sub jet de apă</h3>\n      <ul>\n        <li>Piesele se desfac ușor</li>\n        <li>Deschidere largă, ajungi ușor cu mâna</li>\n        <li>Plastic ABS, fără BPA</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Încarci storcătorul cu cablul USB din colet.</li>\n      <li>Tai fructul în două. Pe cele mari, în patru.</li>\n      <li>Pui fructul pe con și apeși butonul.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 storcător electric portabil de citrice, 500 ml</li>\n      <li>1 cablu de încărcare USB Type-C</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Putere</th><td>45 W</td></tr>\n        <tr><th>Capacitate</th><td>500 ml</td></tr>\n        <tr><th>Încărcare</th><td>USB Type-C (laptop, baterie externă, mașină)</td></tr>\n        <tr><th>Material</th><td>Plastic ABS, fără BPA</td></tr>\n        <tr><th>Dimensiuni</th><td>11 × 10,7 × 23,7 cm</td></tr>\n        <tr><th>Fructe potrivite</th><td>Portocale, lămâi, lime, grepfrut, rodie, struguri și altele</td></tr>\n        <tr><th>Mod de utilizare</th><td>Fructe sub 10 cm – tăiate în jumătate; mai mari – în 4 bucăți</td></tr>\n        <tr><th>Curățare</th><td>Piese detașabile, se spală sub jet de apă</td></tr>\n        <tr><th>Culoare</th><td>Turcoaz</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Trebuie să stea în priză când storc?</h4>\n    <p>Nu. Se încarcă prin cablul USB, iar o încărcare ajunge pentru mai multe utilizări.</p>\n    <h4>Îl pot lua cu mine?</h4>\n    <p>Da. Are 23,7 cm înălțime și îl poți încărca și de la o baterie externă sau din mașină.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A014';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Nopți mai liniștite, cu mai puțini țânțari</h2>\n    <p>Lumina violet atrage țânțarii, iar grila electrică îi oprește. Lampa lucrează fără zgomot și fără spray-uri.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A015-1.webp\" alt=\"Două lămpi UV anti-insecte, cu perie de curățare și cablu USB\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Primești două lămpi, nu una</h3>\n      <ul>\n        <li>Una în dormitor, una în altă cameră</li>\n        <li>Perie de curățare și cablu USB incluse</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A015-2.webp\" alt=\"Grila electrică, lumina UV violet, mânerul și butonul de pornire al lămpii\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Un singur buton, ușor de folosit</h3>\n      <ul>\n        <li>Lumina UV violet atrage țânțarii</li>\n        <li>Ajută la reducerea țânțarilor din cameră</li>\n        <li>Mâner practic, o muți unde vrei</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A015-3.webp\" alt=\"Lampa folosită în dormitor, bucătărie, living și camera copiilor\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Bună în orice cameră din casă</h3>\n      <ul>\n        <li>Silențioasă, nu te deranjează la somn</li>\n        <li>Fără substanțe chimice și fără mirosuri</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A015-4.webp\" alt=\"Dimensiunile lămpii: 16,2 cm înălțime și 9 cm la bază\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Mică și ușor de mutat</h3>\n      <ul>\n        <li>Doar 16,2 cm înălțime</li>\n        <li>O iei pe terasă sau la camping</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum o folosești</h3>\n    <ol>\n      <li>Conectezi cablul USB la un încărcător, laptop sau baterie externă.</li>\n      <li>Apeși butonul de sus ca să o pornești.</li>\n      <li>Din când în când cureți grila cu peria din colet.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 lămpi UV anti-insecte (oferta 1+1 = 2 bucăți)</li>\n      <li>Perie de curățare</li>\n      <li>Cablu USB</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tehnologie</th><td>Lumină UV violet + grilă cu șoc electric</td></tr>\n        <tr><th>Alimentare</th><td>USB – compatibilă cu orice port USB</td></tr>\n        <tr><th>Funcționare</th><td>Silențioasă</td></tr>\n        <tr><th>Substanțe chimice</th><td>Nu folosește</td></tr>\n        <tr><th>Înălțime</th><td>16,2 cm</td></tr>\n        <tr><th>Diametru bază</th><td>9 cm</td></tr>\n        <tr><th>Diametru sus</th><td>6,2 cm</td></tr>\n        <tr><th>Utilizare</th><td>Casă, birou, dormitor, camera copiilor, terasă, camping</td></tr>\n        <tr><th>Accesorii</th><td>Perie de curățare și cablu USB</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Face zgomot noaptea?</h4>\n    <p>Nu. Funcționează silențios, așa că o poți lăsa pornită în dormitor.</p>\n    <h4>Unde o conectez?</h4>\n    <p>La orice port USB: încărcător de priză, laptop sau baterie externă. Cablul USB este în colet.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A015';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Grătar gustos, fără să se lipească nimic</h2>\n    <p>Plita rotundă de 32 cm are strat antiaderent. Gătești pe ea carne, pește, ouă și legume, acasă sau la iarbă verde.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A016-1.webp\" alt=\"Plită rotundă pe un arzător de voiaj, cu frigărui, creveți și legume\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Gătești totul pe aceeași plită</h3>\n      <ul>\n        <li>Carne, mici, pește, ouă, legume, clătite</li>\n        <li>Carnea rămâne suculentă</li>\n        <li>Ai nevoie de mai puțin ulei</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A016-2.webp\" alt=\"Plita pe arzător: temperatură ridicată în mijloc, coacere lentă pe margini\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Fierbinte la mijloc, blândă pe margini</h3>\n      <ul>\n        <li>În centru prăjești repede</li>\n        <li>Pe margini coci încet, fără să arzi</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A016-3.webp\" alt=\"Plita rotundă ținută de cele două mânere laterale\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Mânere comode, bună la camping</h3>\n      <ul>\n        <li>Două mânere laterale, o ridici în siguranță</li>\n        <li>Merge pe aragaz și pe arzător de voiaj</li>\n        <li>Nu se deformează la temperaturi ridicate</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A016-4.webp\" alt=\"Plita agățată de mâner pe o bară și pusă în dulap, sub farfurii\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Ocupă puțin loc în bucătărie</h3>\n      <ul>\n        <li>Mânerele au găuri pentru agățat</li>\n        <li>Fiind plată, încape ușor în dulap</li>\n        <li>O cureți cu un prosop umed</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 plite rotunde antiaderente de 32 cm (oferta 1+1 = 2 bucăți)</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Diametru</th><td>32 cm</td></tr>\n        <tr><th>Suprafață</th><td>Strat antiaderent, efect granit</td></tr>\n        <tr><th>Distribuția căldurii</th><td>Temperatură ridicată în centru, coacere lentă pe laterale</td></tr>\n        <tr><th>Compatibilitate</th><td>Aragaz, plită cu gaz, arzător de camping / voiaj</td></tr>\n        <tr><th>Mânere</th><td>Ergonomice, laterale, cu găuri pentru agățare</td></tr>\n        <tr><th>Rezistență</th><td>Temperaturi ridicate, utilizare intensă, nu se deformează</td></tr>\n        <tr><th>Curățare</th><td>Cu un prosop umed</td></tr>\n        <tr><th>Culoare</th><td>Negru, efect granit</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Pe ce o pot folosi?</h4>\n    <p>Pe aragaz, pe plită cu gaz sau pe arzător de camping.</p>\n    <h4>Cum o curăț?</h4>\n    <p>Stratul antiaderent nu lasă mâncarea să se lipească. De obicei ajunge să o ștergi cu un prosop umed.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A016';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Bucle frumoase acasă, în câteva minute</h2>\n    <p>Ondulatorul cu 3 tuburi prinde o șuviță întreagă dintr-o singură apăsare. Valurile ies egale, fără drum la coafor.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A017-1.webp\" alt=\"Femeie cu păr lung ondulat și ondulatorul cu trei tuburi\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Valuri egale dintr-o singură trecere</h3>\n      <ul>\n        <li>3 tuburi de 24 mm lucrează deodată</li>\n        <li>Coafura e gata în 10–15 minute</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A017-2.webp\" alt=\"Femeie care își ondulează o șuviță de păr cu ondulatorul triplu\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Ușor de folosit, și de una singură</h3>\n      <ul>\n        <li>Se folosește pe păr uscat</li>\n        <li>Se încălzește în aproximativ 30 de secunde</li>\n        <li>Cablul se rotește 360° și nu te încurcă</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A017-3.webp\" alt=\"Cele trei tuburi cu acoperire ceramică, văzute de aproape\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Tuburi cu acoperire ceramică</h3>\n      <ul>\n        <li>Căldura se împarte egal pe șuviță</li>\n        <li>Alunecă ușor prin păr</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A017-4.webp\" alt=\"Ondulator triplu de 24 mm, cu butonul de temperatură pe mâner\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Alegi căldura potrivită părului tău</h3>\n      <ul>\n        <li>180°C pentru păr fin sau vopsit</li>\n        <li>210°C pentru păr gros</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Îl bagi în priză și alegi temperatura.</li>\n      <li>Aștepți aproximativ 30 de secunde să se încălzească.</li>\n      <li>Prinzi pe rând câte o șuviță de păr uscat.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 ondulator de păr cu 3 tuburi de 24 mm, cu acoperire ceramică</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Ondulator de păr cu 3 tuburi</td></tr>\n        <tr><th>Diametru tuburi</th><td>24 mm</td></tr>\n        <tr><th>Temperaturi</th><td>2 trepte: 180°C și 210°C</td></tr>\n        <tr><th>Timp de încălzire</th><td>Aproximativ 30 de secunde</td></tr>\n        <tr><th>Acoperire</th><td>Ceramică</td></tr>\n        <tr><th>Tensiune / Putere</th><td>110–240 V / 70–130 W</td></tr>\n        <tr><th>Cablu</th><td>Rotativ 360°</td></tr>\n        <tr><th>Utilizare</th><td>Pe păr uscat</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Ce temperatură aleg?</h4>\n    <p>180°C pentru păr fin sau vopsit. 210°C pentru păr gros, care se ondulează mai greu.</p>\n    <h4>Îl folosesc pe păr ud sau uscat?</h4>\n    <p>Doar pe păr uscat.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A017';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Cafea proaspăt măcinată, în câteva secunde</h2>\n    <p>Pui boabele, apeși butonul și râșnița macină singură. Merge și pentru nuci, zahăr, piper sau scorțișoară.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A018-1.webp\" alt=\"Râșniță electrică din inox lângă semințe, boabe și condimente\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Macină mai mult decât cafea</h3>\n      <ul>\n        <li>Cafea, nuci, semințe, piper, scorțișoară</li>\n        <li>Faci zahăr pudră din zahăr obișnuit</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A018-2.webp\" alt=\"Râșnița electrică de 150 W, cutia ei și bolul cu lame din oțel inoxidabil\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Motor de 150 W, lame din inox</h3>\n      <ul>\n        <li>Macină fin în câteva secunde</li>\n        <li>Lamele și bolul sunt din oțel inoxidabil</li>\n        <li>Pornești dintr-un singur buton</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A018-3.webp\" alt=\"Bolul din oțel inoxidabil și capacul transparent al râșniței\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Vezi prin capac cât de fin e</h3>\n      <ul>\n        <li>Capac transparent: te oprești când vrei</li>\n        <li>Bolul din inox se șterge repede</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A018-4.webp\" alt=\"Râșnița electrică lângă boabe de cafea și o ceașcă de cafea\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Mică, încape în orice dulap</h3>\n      <ul>\n        <li>Doar 17 × 10 cm</li>\n        <li>Macină 50–100 g o dată</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum o folosești</h3>\n    <ol>\n      <li>Pui boabele sau condimentele în bol și așezi capacul.</li>\n      <li>Bagi râșnița în priză și apeși butonul.</li>\n      <li>Te oprești când e măcinat destul de fin.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 râșniță electrică de 150 W, cu bol din oțel inoxidabil</li>\n      <li>Capac transparent din plastic</li>\n      <li>Cablu de alimentare pentru priză de 220 V</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Putere motor</th><td>150 W</td></tr>\n        <tr><th>Capacitate</th><td>50–100 g</td></tr>\n        <tr><th>Bol și lame</th><td>Oțel inoxidabil</td></tr>\n        <tr><th>Capac</th><td>Plastic transparent</td></tr>\n        <tr><th>Utilizări</th><td>Cafea, nuci, zahăr, scorțișoară, piper, condimente</td></tr>\n        <tr><th>Alimentare</th><td>Priză 220 V</td></tr>\n        <tr><th>Dimensiuni</th><td>17 × 10 cm</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Ce pot măcina în ea?</h4>\n    <p>Cafea, nuci, zahăr, semințe, piper, scorțișoară și alte condimente.</p>\n    <h4>Cum o curăț?</h4>\n    <p>Scoți râșnița din priză și ștergi bolul din inox. Lamele nu ruginesc și nu păstrează mirosuri.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A018';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Frișcă și aluat fără să te doară mâna</h2>\n    <p>Mixerul de mână cu 7 viteze amestecă în locul tău. Tu doar îl ții și alegi viteza potrivită.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A019-1.webp\" alt=\"Mixer de mână alb cu 7 viteze, cu teluri și cârlige de aluat din inox\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>7 viteze și 4 palete din inox</h3>\n      <ul>\n        <li>2 teluri pentru frișcă, creme și albușuri</li>\n        <li>2 cârlige pentru aluat de cozonac, pâine, pizza</li>\n        <li>Mâner comod, ușor de ținut</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Pui telurile sau cârligele în mixer.</li>\n      <li>Pornești încet, ca să nu împrăștii făina, apoi crești viteza.</li>\n      <li>La final scoți paletele și le clătești.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 mixere de mână cu 7 viteze (ofertă 1+1)</li>\n      <li>Pentru fiecare mixer: 2 teluri din oțel inoxidabil</li>\n      <li>Pentru fiecare mixer: 2 cârlige de aluat din oțel inoxidabil</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Mixer de mână</td></tr>\n        <tr><th>Trepte de viteză</th><td>7 viteze</td></tr>\n        <tr><th>Alimentare</th><td>220V / 50Hz</td></tr>\n        <tr><th>Material</th><td>ABS + oțel inoxidabil</td></tr>\n        <tr><th>Accesorii</th><td>4 palete detașabile (2 teluri + 2 cârlige de aluat)</td></tr>\n        <tr><th>Culoare</th><td>Alb</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Pot face și aluat de cozonac cu el?</h4>\n    <p>Da. Pentru aluat folosești cele 2 cârlige. Pentru frișcă, creme și albușuri folosești telurile.</p>\n    <h4>Cum se curăță?</h4>\n    <p>Paletele se scot ușor. Le clătești sub jet de apă și gata.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A019';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Curăță cu apă acolo unde periuța nu ajunge</h2>\n    <p>Irigatorul oral trimite un jet fin de apă între dinți și pe lângă gingii. Ajută la îndepărtarea resturilor de mâncare.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A020-1.webp\" alt=\"Irigator oral portabil cu 4 capete, lângă cutia lui\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Pentru zonele greu de curățat</h3>\n      <ul>\n        <li>Jet de apă între dinți și lângă gingii</li>\n        <li>Comod și pentru aparat dentar</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A020-2.webp\" alt=\"Irigator oral ținut în mână și cele 3 moduri: Soft, Normal, Pulse\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>3 moduri, alegi tu puterea jetului</h3>\n      <ul>\n        <li>Soft: jet delicat, gingii sensibile</li>\n        <li>Normal: curățarea de zi cu zi</li>\n        <li>Pulse: jet pulsat, masajul gingiilor</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A020-3.webp\" alt=\"Două irigatoare orale cu rezervor de 220 ml și cele 4 duze incluse\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Fără fir, îl iei oriunde</h3>\n      <ul>\n        <li>Rezervor de 220 ml, se umple la robinet</li>\n        <li>Se încarcă prin USB</li>\n        <li>O încărcare ține până la 30 de zile</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A020-4.webp\" alt=\"Cele 4 duze: standard, pentru limbă, parodontală și ortodontică\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>4 duze, fiecare cu rolul ei</h3>\n      <ul>\n        <li>Duză standard și duză pentru limbă</li>\n        <li>Duză parodontală și duză ortodontică</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Umpli rezervorul și pui duza dorită.</li>\n      <li>Alegi modul din buton.</li>\n      <li>Plimbi jetul între dinți și pe lângă gingii.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 irigatoare orale portabile (ofertă 1+1)</li>\n      <li>Câte 4 duze pentru fiecare irigator</li>\n      <li>Cablu de încărcare USB și manual de utilizare</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Irigator oral portabil (duș bucal)</td></tr>\n        <tr><th>Rezervor</th><td>220 ml</td></tr>\n        <tr><th>Moduri</th><td>3: Soft, Normal, Pulse</td></tr>\n        <tr><th>Duze</th><td>4: standard, pentru limbă, parodontală, ortodontică</td></tr>\n        <tr><th>Alimentare</th><td>Baterie reîncărcabilă prin USB</td></tr>\n        <tr><th>Autonomie</th><td>Până la 30 de zile cu o încărcare</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Înlocuiește periuța de dinți?</h4>\n    <p>Nu. Îl folosești pe lângă periuță. Nu este un tratament și nu înlocuiește vizita la stomatolog.</p>\n    <h4>Îl pot folosi dacă am gingii sensibile?</h4>\n    <p>Da. Alegi modul Soft, cu jet delicat, și duza parodontală.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A020';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Masaj pentru ceafă, la tine acasă</h2>\n    <p>Aparatul SIKS se pune pe gât ca niște căști. Îți oferă o senzație de relaxare după o zi lungă.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A021-1.webp\" alt=\"Aparat de masaj cervical SIKS alb cu gri, în formă de U\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Formă de U, după curba gâtului</h3>\n      <ul>\n        <li>Se potrivește pe orice mărime de gât</li>\n        <li>Ușor, se poartă ca niște căști</li>\n        <li>Culoare alb cu gri</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A021-2.webp\" alt=\"Detalii: cele două capete de masaj și butoanele aparatului\" width=\"720\" height=\"378\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Alegi masajul care îți place</h3>\n      <ul>\n        <li>4 moduri de masaj</li>\n        <li>15 niveluri, de la blând la intens</li>\n        <li>2 capete de masaj, așezate pe ceafă</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A021-3.webp\" alt=\"Femeie care poartă aparatul de masaj pe gât, fără fir\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Fără fir, îl porți oriunde</h3>\n      <ul>\n        <li>Acumulator care se încarcă cu cablul inclus</li>\n        <li>Îl folosești când citești sau te uiți la televizor</li>\n        <li>Ajută la relaxarea mușchilor gâtului</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Îl încarci cu cablul din colet.</li>\n      <li>Îl așezi pe gât, cu cele 2 capete pe ceafă.</li>\n      <li>Alegi din butoane modul și intensitatea. Ajung 15 minute pe zi.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 aparat de masaj cervical SIKS, alb/gri</li>\n      <li>1 cablu de încărcare</li>\n      <li>1 manual de utilizare</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Aparat inteligent de masaj cervical</td></tr>\n        <tr><th>Moduri de masaj</th><td>4 moduri</td></tr>\n        <tr><th>Niveluri de intensitate</th><td>15 niveluri reglabile</td></tr>\n        <tr><th>Capete de masaj</th><td>2 capete, poziționate ergonomic</td></tr>\n        <tr><th>Design</th><td>Formă de U, stil căști, fără fir, potrivit oricărei dimensiuni a gâtului</td></tr>\n        <tr><th>Alimentare</th><td>Acumulator reîncărcabil, cablu inclus</td></tr>\n        <tr><th>Culoare</th><td>Alb / Gri</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Este un aparat medical?</h4>\n    <p>Nu. Este un aparat de masaj pentru relaxare. Nu este un tratament și nu înlocuiește sfatul medicului.</p>\n    <h4>Dacă masajul e prea tare pentru mine?</h4>\n    <p>Ai 15 niveluri de intensitate. Începi cu cel mai mic și crești doar cât îți este plăcut.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A021';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Vezi în 5 secunde cât arată alcoolemia</h2>\n    <p>Sufli în aparat și citești rezultatul pe ecran. Alcooltest mic, de buzunar, cu 4 capete de rezervă.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A022-1.webp\" alt=\"Alcooltest digital ținut în mână, cu rezultatul afișat pe ecran\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Rezultat clar, pe ecran luminat</h3>\n      <ul>\n        <li>Afișează în g/l și în % BAC</li>\n        <li>Ecran LCD luminat, se vede și noaptea</li>\n        <li>Breloc, îl prinzi la chei</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A022-2.webp\" alt=\"Persoană care suflă în alcooltestul portabil\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Sufli și aștepți cel mult 5 secunde</h3>\n      <ul>\n        <li>Senzor care măsoară alcoolul din respirație</li>\n        <li>Ține minte ultimele 20 de măsurători</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A022-3.webp\" alt=\"Alcooltest cu ecran roșu lângă un pahar de vin\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Te anunță când valoarea e ridicată</h3>\n      <ul>\n        <li>Ecranul își schimbă culoarea</li>\n        <li>Alertă sonoră la valori mari</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A022-4.webp\" alt=\"Alcooltestul cu cele 4 capete de schimb, butonul de pornire și ecranul\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>4 capete de schimb, un singur buton</h3>\n      <ul>\n        <li>Îl pot folosi igienic mai multe persoane</li>\n        <li>Se oprește singur după test</li>\n        <li>Peste 200 de teste cu un set de baterii</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Pui 2 baterii AAA și un capăt curat.</li>\n      <li>Apeși butonul de pornire.</li>\n      <li>Sufli în capăt și citești valoarea pe ecran.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 alcooltest digital cu breloc</li>\n      <li>4 capete de schimb (muștiucuri)</li>\n      <li>Bateriile nu sunt incluse (2 baterii AAA)</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Alcooltest digital</td></tr>\n        <tr><th>Interval de testare</th><td>0,00 – 0,19% BAC (0,0 – 1,9 g/l)</td></tr>\n        <tr><th>Timp de măsurare</th><td>Maximum 5 secunde</td></tr>\n        <tr><th>Afișaj</th><td>LCD cu iluminare de fundal, două culori + alertă sonoră</td></tr>\n        <tr><th>Memorie</th><td>Ultimele 20 de măsurători</td></tr>\n        <tr><th>Alimentare</th><td>2 baterii AAA (peste 200 de teste / set), nu sunt incluse</td></tr>\n        <tr><th>Funcții extra</th><td>Oprire automată, economisire energie, breloc</td></tr>\n        <tr><th>Dimensiuni / Greutate</th><td>110 × 75 mm / 100 g</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Pot să mă bazez pe rezultat ca să conduc?</h4>\n    <p>Nu. Rezultatul este orientativ și nu înlocuiește testul poliției. Dacă ai băut alcool, nu te urca la volan.</p>\n    <h4>Ce baterii îi trebuie?</h4>\n    <p>2 baterii AAA. Nu sunt incluse în colet.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A022';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Scoți tortul întreg din tavă</h2>\n    <p>Set de 3 tăvi antiaderente: rotundă, pătrată și inimă. Desfaci marginea, iar tortul rămâne frumos pe bază.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A023-1.webp\" alt=\"Cele 3 tăvi de tort așezate una în alta: pătrată, rotundă și inimă\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>3 tăvi care intră una în alta</h3>\n      <ul>\n        <li>Rotundă, pătrată și în formă de inimă</li>\n        <li>În dulap ocupă locul unei singure tăvi</li>\n        <li>Strat antiaderent, cu bază gofrată</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A023-2.webp\" alt=\"Marginea tăvii rotunde ridicată de pe blatul copt\" width=\"449\" height=\"451\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Desfaci clapeta și ridici marginea</h3>\n      <ul>\n        <li>Blatul rămâne întreg pe bază</li>\n        <li>Poți coace și fără hârtie de copt</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A023-3.webp\" alt=\"Tort rotund, prăjitură pătrată și desert în formă de inimă, făcute în cele 3 tăvi\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Altă formă pentru fiecare desert</h3>\n      <ul>\n        <li>Tort rotund sau prăjitură pătrată</li>\n        <li>Rezistă la temperaturi înalte, în orice cuptor</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A023-4.webp\" alt=\"Tava în formă de inimă lângă un tort inimă, plus alte preparate făcute în tăvi\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Tort inimă pentru zile speciale</h3>\n      <ul>\n        <li>Bună și pentru cheesecake, tarte sau pizza</li>\n        <li>Se spală și la mașina de spălat vase</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum le folosești</h3>\n    <ol>\n      <li>Închizi clapeta laterală și torni compoziția.</li>\n      <li>Coci ca de obicei.</li>\n      <li>Desfaci clapeta și ridici marginea de pe tort.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 tavă rotundă cu bază detașabilă (22 cm)</li>\n      <li>1 tavă pătrată cu bază detașabilă (24 × 24 cm)</li>\n      <li>1 tavă inimă cu bază detașabilă (20 cm)</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Set 3 tăvi teflonate cu baze detașabile</td></tr>\n        <tr><th>Tavă inimă</th><td>20 × 6,8 cm</td></tr>\n        <tr><th>Tavă rotundă</th><td>22 × 6,8 cm</td></tr>\n        <tr><th>Tavă pătrată</th><td>24 × 24 × 6,8 cm</td></tr>\n        <tr><th>Suprafață</th><td>Antiaderentă, cu bază gofrată</td></tr>\n        <tr><th>Sistem de deschidere</th><td>Clapetă laterală + bază detașabilă</td></tr>\n        <tr><th>Rezistență</th><td>Temperaturi înalte, orice cuptor</td></tr>\n        <tr><th>Curățare</th><td>Compatibile cu mașina de spălat vase</td></tr>\n        <tr><th>Ideale pentru</th><td>Torturi, cheesecake, tarte, pizza, deserturi reci sau coapte</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Trebuie să pun hârtie de copt?</h4>\n    <p>Nu este nevoie. Tăvile au strat antiaderent și bază gofrată, ca prăjitura să se desprindă ușor.</p>\n    <h4>Le pot folosi și pentru deserturi reci?</h4>\n    <p>Da. Sunt bune pentru cheesecake și alte deserturi reci, dar și pentru tarte sau pizza.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau onlin