UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Apă mai curată, direct de la robinetul tău</h2>\n    <p>Filtrul cu cărbune activ se prinde pe robinet în 2 minute. Nu mai cari bidoane grele de la magazin.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A024-1.webp\" alt=\"Filtru de apă montat pe robinetul din bucătărie\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Se montează singur, fără instalator</h3>\n      <ul>\n        <li>Se înșurubează direct pe robinet</li>\n        <li>Se potrivește pe robinetele standard</li>\n        <li>Gata de folosit în 2 minute</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A024-2.webp\" alt=\"Fructe spălate cu apă filtrată de la robinet\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Apă bună de băut și de gătit</h3>\n      <ul>\n        <li>Ajută la reducerea clorului, ruginii și sedimentelor</li>\n        <li>Cafea și ceai fără gust de clor</li>\n        <li>Un buton alege: apă filtrată sau apă normală</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/A024-3.webp\" alt=\"Piesele filtrului: carcasă, element filtrant și conector\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Un filtru ține minimum 90 de zile</h3>\n      <ul>\n        <li>Filtrează aproximativ 1.000 de litri</li>\n        <li>Elementul filtrant se clătește sub jet și se refolosește</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Alegi adaptorul potrivit și prinzi filtrul pe robinet.</li>\n      <li>Rotești butonul lateral pe „apă filtrată”.</li>\n      <li>Lași apa să curgă câteva secunde și e gata.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 filtru de apă pentru robinet, cu carcasă</li>\n      <li>1 element filtrant cu cărbune activ</li>\n      <li>Adaptoare pentru robinete standard</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Filtru de apă pentru robinet, cu cărbune activ</td></tr>\n        <tr><th>Durată filtru</th><td>Minimum 90 de zile / 1.000 litri</td></tr>\n        <tr><th>Debit maxim</th><td>2 litri pe minut</td></tr>\n        <tr><th>Carcasă</th><td>5,5 cm lățime × 10 cm înălțime</td></tr>\n        <tr><th>Element filtrant</th><td>4 cm lățime × 10 cm înălțime</td></tr>\n        <tr><th>Dispozitiv de montaj</th><td>8 cm lățime, pentru robinete standard</td></tr>\n        <tr><th>Curățare</th><td>Elementul filtrant se spală sub jet de apă; calota ceramică se curăță cu hârtie abrazivă</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Se potrivește pe robinetul meu?</h4>\n    <p>Se potrivește pe robinetele standard de bucătărie. În colet găsești adaptoare.</p>\n    <h4>Pot folosi și apă nefiltrată?</h4>\n    <p>Da. Rotești butonul lateral și curge apă normală, de exemplu pentru vase. Așa filtrul ține mai mult.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A024';

