h><td>Set boluri din inox cu capace</td></tr>\n        <tr><th>Număr de piese</th><td>10: 5 boluri + 5 capace</td></tr>\n        <tr><th>Diametre boluri</th><td>10, 12, 14, 16 și 18 cm</td></tr>\n        <tr><th>Material boluri</th><td>Inox</td></tr>\n        <tr><th>Capace</th><td>Transparente</td></tr>\n        <tr><th>Utilizare</th><td>Preparare, servire și depozitare</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Are fiecare bol capacul lui?</h4>\n    <p>Da. Setul are 5 boluri și 5 capace transparente, câte unul pentru fiecare mărime.</p>\n    <h4>Ocupă mult loc în dulap?</h4>\n    <p>Nu. Când nu le folosești, bolurile ocupă puțin spațiu.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'A025X2';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Două filtre de apă pentru robinetele tale</h2>\n    <p>Filtrul se prinde direct pe robinet. Ajută la reducerea clorului și a sedimentelor. În colet vin 2 bucăți.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/af988360-5720-4a02-84e9-d84449aa15b4-1.webp\" alt=\"Filtru de apă montat pe robinet, cu un fruct spălat sub jet\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Apă mai plăcută la gust și miros</h3>\n      <ul>\n        <li>Ajută la reducerea clorului, sedimentelor și impurităților</li>\n        <li>Bună pentru spălat fructe și legume</li>\n        <li>Se fixează direct pe robinet</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/af988360-5720-4a02-84e9-d84449aa15b4-2.webp\" alt=\"Piesele filtrului: carcasă, filtru de apă, conector și manetă\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Puține piese, montaj fără instalator</h3>\n      <ul>\n        <li>Strângi conectorul pe robinet și gata</li>\n        <li>Maneta laterală alege: apă filtrată sau normală</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum îl folosești</h3>\n    <ol>\n      <li>Verifici dacă adaptorul se potrivește pe robinet.</li>\n      <li>Fixezi filtrul și strângi conectorul.</li>\n      <li>Alegi apa filtrată din manetă și lași să curgă câteva secunde.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>2 filtre de apă pentru robinet (ofertă 1+1)</li>\n      <li>Pui unul la bucătărie și unul la alt robinet</li>\n      <li>Sau îl păstrezi pe al doilea ca rezervă</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Tip produs</th><td>Filtru de apă pentru robinet</td></tr>\n        <tr><th>Bucăți în colet</th><td>2 filtre (1+1)</td></tr>\n        <tr><th>Montaj</th><td>Direct pe robinetele compatibile, cu adaptor și conector</td></tr>\n        <tr><th>Comutare</th><td>Manetă laterală: flux filtrat sau flux normal</td></tr>\n        <tr><th>Piese</th><td>Carcasă filtru, filtru de apă, conector pentru robinet</td></tr>\n        <tr><th>Prima folosire</th><td>Lași apa să curgă câteva secunde</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Se potrivește pe robinetul meu?</h4>\n    <p>Depinde de forma și mărimea robinetului. Înainte de montaj verifici dacă adaptorul se potrivește.</p>\n    <h4>Face apa nepotabilă bună de băut?</h4>\n    <p>Nu. Filtrul nu transformă apa nepotabilă în apă potabilă. El ajută la reducerea clorului, sedimentelor și impurităților.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'af988360-5720-4a02-84e9-d84449aa15b4';

UPDATE products SET description = '<div class=\"lpd\">\n  <div class=\"lpd-hook\">\n    <h2>Păr aranjat și bucle frumoase, acasă</h2>\n    <p>Pachet cu două aparate: perie cu aer cald pentru uscat și aranjat, plus ondulator triplu pentru bucle uniforme.</p>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/c7fc7a2a-b5d6-435d-8919-9ca5eaf55ab5-1.webp\" alt=\"Femeie cu bucle ample făcute cu ondulatorul triplu\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Bucle ample, fără drum la salon</h3>\n      <ul>\n        <li>Cele trei bare fac onduleuri uniforme</li>\n        <li>Pentru onduleuri lejere sau bucle bine definite</li>\n        <li>Schimbi coafura când vrei, la tine acasă</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/c7fc7a2a-b5d6-435d-8919-9ca5eaf55ab5-2.webp\" alt=\"Peria cu aer cald: orificii de aer, mâner ergonomic și buton cu trepte\" width=\"552\" height=\"581\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Peria usucă și aranjează deodată</h3>\n      <ul>\n        <li>Putere de 1000 W</li>\n        <li>3 trepte de temperatură și viteză</li>\n        <li>Orificii de aer și mâner ergonomic</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-feature\">\n    <img src=\"/shoptop-api/uploads/landing/c7fc7a2a-b5d6-435d-8919-9ca5eaf55ab5-3.webp\" alt=\"Ondulator triplu cu trei bare de 24 mm\" width=\"720\" height=\"720\" loading=\"lazy\">\n    <div class=\"lpd-feature__body\">\n      <h3>Ondulator cu trei bare de 24 mm</h3>\n      <ul>\n        <li>Două trepte: 180°C și 210°C</li>\n        <li>Bare cu acoperire ceramică</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"lpd-steps\">\n    <h3>Cum le folosești</h3>\n    <ol>\n      <li>Usuci și aranjezi părul cu peria cu aer cald.</li>\n      <li>Alegi treapta de temperatură la ondulator.</li>\n      <li>Prinzi șuvițele pe rând între bare, pentru bucle.</li>\n    </ol>\n  </div>\n\n  <div class=\"lpd-box\">\n    <h3>Ce primești în colet</h3>\n    <ul>\n      <li>1 perie de păr cu aer cald</li>\n      <li>1 ondulator triplu, cu bare de 24 mm</li>\n    </ul>\n  </div>\n\n  <details class=\"lpd-more\">\n    <summary>Specificații tehnice</summary>\n    <table>\n      <tbody>\n        <tr><th>Pachet</th><td>Perie cu aer cald + ondulator triplu</td></tr>\n        <tr><th>Perie: putere</th><td>1000 W</td></tr>\n        <tr><th>Perie: trepte</th><td>3 trepte de temperatură și viteză</td></tr>\n        <tr><th>Perie: detalii</th><td>Orificii de aer pentru distribuirea fluxului, mâner ergonomic</td></tr>\n        <tr><th>Ondulator: bare</th><td>3 bare de 24 mm, cu acoperire ceramică</td></tr>\n        <tr><th>Ondulator: temperatură</th><td>2 trepte: 180°C și 210°C</td></tr>\n      </tbody>\n    </table>\n  </details>\n\n  <details class=\"lpd-more\">\n    <summary>Întrebări frecvente</summary>\n    <h4>Am nevoie și de uscător de păr?</h4>\n    <p>Peria cu aer cald ajută la uscarea și aranjarea părului în același timp.</p>\n    <h4>La ce să am grijă?</h4>\n    <p>Folosește aparatele după instrucțiuni. Barele ondulatorului sunt fierbinți, nu le atinge de piele.</p>\n    <h4>Cum plătesc?</h4>\n    <p>La curier, când primești coletul, sau online cu cardul.</p>\n  </details>\n</div>' WHERE id = 'c7fc7a2a-b5d6-435d-8919-9ca5eaf55ab5';

